<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'; import { api } from '../api'; import SubscriptionLinks from '../components/SubscriptionLinks.vue';
const form=reactive({checkIntervalHours:24,requestTimeoutMs:10000,failureThreshold:3,cacheTime:7200});const busy=ref(false),message=ref(''),error=ref('');
onMounted(async()=>{try{Object.assign(form,await api.get('/api/admin/settings'))}catch(e){error.value=e instanceof Error?e.message:'载入失败'}});async function save(){busy.value=true;message.value='';error.value='';try{Object.assign(form,await api.send('/api/admin/settings','PUT',form));message.value='设置已保存，调度器已重新安排。'}catch(e){error.value=e instanceof Error?e.message:'保存失败'}finally{busy.value=false}}
</script>
<template><section><div class="page-head"><div><div class="eyebrow">SETTINGS</div><h1>运行设置</h1></div></div><form class="panel settings" @submit.prevent="save"><div class="form-grid"><label>检测间隔（小时）<input v-model.number="form.checkIntervalHours" type="number" min="1" max="8760" required><small>每轮全量检测之间的时间</small></label><label>请求超时（毫秒）<input v-model.number="form.requestTimeoutMs" type="number" min="100" max="300000" required></label><label>失败阈值<input v-model.number="form.failureThreshold" type="number" min="1" max="100" required><small>连续失败达到此值后隐藏来源</small></label><label>缓存时间（秒）<input v-model.number="form.cacheTime" type="number" min="1" max="31536000" required></label></div><p v-if="message" class="good" role="status">{{message}}</p><p v-if="error" class="error">{{error}}</p><button class="primary" :disabled="busy">{{busy?'保存中…':'保存设置'}}</button></form><SubscriptionLinks/></section></template>
